@module sonority  src=sonority.lua  loc=243  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state, no ratios, no cents — coords, strikes, classes in, indices out  @ 5

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 6
  @shape  Strand = { notes={ {ppq,pitch,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes and the class only  @ 7
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, at most n entries  @ 8
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 9

# Imports
  @const util = 'util'  @ 11

# Module-level constants
  @const sonority = {}  @ 12
  @const weights = {}  @ 17
  @const budget = 200000  @ 149

# Private functions
  -- The box
  @fn weight(prime)  @ 18-22
  -- The walk
  @fn strikesInOrder(strands)  @ 50-63
      -- Every strike, in onset order, lowest last — so a released chord leaves its
      -- bass to the sonority that follows (design/adaptive-tuning.md § The model).
  @fn promote(recent, strands, index)  @ 67-73
      -- The class holds one entry however many notes write it: a restrike moves its
      -- own entry to the front, and a second strand of the class takes the entry over.
  -- The objective
  -- The solve
  @fn schedule(strands, sonorities)  @ 119-145
      -- A strand is live from the onset it is chosen at to the last that reads it, both
      -- known before enumeration (§ Solving it), and listed in strand order for keying.
      @contract  strands, sonorities → per onset the strands born there, live there, and held from before  @ 118
  @fn assertAffordable(strands, plan)  @ 151-161
  @fn placementsAt(strands, born, strength)  @ 165-184
      -- Every combination of the shortlists of the strands born at an onset, with the
      -- pull each charges — the same against every state, so charged once here.
  @fn keyOf(choice, list)  @ 186-190

# Public API (sonority.*)
  @api sonority.score(coordSet)  @ 28-44
      -- The axes are gathered before any is measured: a member holding no exponent on
      -- an axis sits at 0 there, and that 0 is only in the span once the axis is known
      -- to exist — an axis every member names does not reach back to the origin.
      @contract  coords[] → Σ over the odd primes of (highest exponent − lowest) × log₂ p  @ 27
  @api sonority.walk(strands, n)  @ 78-91
      -- The whole onset is absorbed before the window is trimmed, so a chord wider
      -- than n leaves its own lowest notes standing rather than its predecessor's.
      @contract  strands, n → a Sonority per distinct onset, the last n distinct classes struck so far  @ 77
  @api sonority.cost(strands, n, strength, choice)  @ 98-112
      -- The pull is counted once per strand rather than once per note, so an octave
      -- doubling changes no answer: the box already charges it nothing.
      @contract  strands, n, strength, choice → box over the walk + strength × strain² per strand  @ 97
  @api sonority.solve(strands, n, strength)  @ 195-241
      -- The state carries the whole choice vector rather than a backpointer: two
      -- generations are alive at a time and the budget bounds them.
      @contract  strands, n, strength → the index per strand minimising sonority.cost, exactly  @ 194

# Uses (outbound edges)
  @use call    util.add  @ strikesInOrder:54 walk:88 cost:103 schedule:138,140,141 placementsAt:174
  @use call    util.clone  @ walk:87 placementsAt:174 solve:221
  @use call    util.key  @ keyOf:189 solve:204
  @use require util  @ <load>:11

# Calls (intra-file)
  @call assertAffordable  @ solve:202
  @call keyOf  @ solve:210,230
  @call placementsAt  @ solve:219
  @call promote  @ walk:83
  @call schedule  @ solve:201
  @call sonority.score  @ cost:105 solve:229
  @call sonority.walk  @ cost:100 solve:200
  @call strikesInOrder  @ walk:79
  @call weight  @ score:41

