  @field w pitch  @ strikesInOrder:54
  @field r ppq  @ strikesInOrder:54,58 walk:81,82 schedule:121,125,127
  @field w ppq  @ strikesInOrder:54 walk:88
  @field r pull  @ solve:229
  @field w pull  @ placementsAt:174
  @field w score  @ score:28
